{"generate":"(block, generator) => {
  const device = generator.valueToCode(block, 'device', generator.ORDER_NONE) || 'None';
  const timeout = generator.valueToCode(block, 'timeout', generator.ORDER_NONE) || '10';
  const args = `'${block.id}', ${device}, ${timeout}`
  const isReturn = block.getFieldValue('isReturn');
  const codeText = `await gripper_get_grip_position(${args})`;
  if(isReturn == 'TRUE') {
    return [codeText, generator.ORDER_NONE]
  }else{
    return codeText + '\n'
  }
}","controller":"(Blockly) => {
  return {
    init() {
      const methodOptions = new Blockly.FieldCheckbox('TRUE');
      methodOptions.setValidator(function(value){
        this.getSourceBlock().updateStatement_(value=='FALSE')
      });
      this.appendDummyInput().appendField(methodOptions, 'isReturn');
      this.appendValueInput("device")
        .appendField(`${Blockly.Msg.Claw}`)
        .setCheck(null);
      this.appendDummyInput()
        .appendField(`${Blockly.Msg.Get_gripping_distance}`)
      this.appendValueInput("timeout")
        .appendField(`${Blockly.Msg.Timeout}`)
        .setCheck(null);
      this.setColour(230);
      this.setOutput(true);
    },
    defaultInputs:{
      'timeout': {
        'shadow': {
          'type': 'math_number',
          'fields': {
            'NUM': 10
          }
        }
      },
    },
    saveExtraState:function(){
      return this.outputConnection?{isStatement:false}:{isStatement:true}
    },
    loadExtraState:function(xmlElement){
      if(xmlElement.isStatement){
        this.updateStatement_(true)
      }else{
        this.updateStatement_(false)
      }
    },
    updateStatement_:function(value){
      if(value!==!this.outputConnection){
        this.unplug(true);
        if(value){
          this.setOutput(false);
          this.setPreviousStatement(true);
          this.setNextStatement(true);
        }else{
          this.setPreviousStatement(false);
          this.setNextStatement(false);
          this.setOutput(true);
        }
      }
    },
  }
}"}

